import * as T from './vendor/three.module.min.js';
const textures=new Map(),tasks=new Map();
const channels=['basecolor','normal','roughness','ao','height','metalness'];
const exterior=['lava-rock','carved-wood','thatch','bamboo'],inside=['woven-mat','floor-slate','red-vinyl','counter-wood'];
async function load(key,file=key+'.png',repeat=true){if(textures.has(key))return textures.get(key);const t=await new T.TextureLoader().loadAsync(new URL('./textures/tiki-v76/'+file,import.meta.url).href);t.name='Tiki generated / '+key;t.colorSpace=/basecolor$|^sign$|^menu$|^fringe$|^tabletop$/.test(key)?T.SRGBColorSpace:T.NoColorSpace;t.wrapS=t.wrapT=repeat?T.RepeatWrapping:T.ClampToEdgeWrapping;t.minFilter=T.LinearMipmapLinearFilter;t.magFilter=T.LinearFilter;t.anisotropy=4;textures.set(key,t);return t;}
export function initializeTikiTextures(interior=false,report=()=>{}){const id=interior?'inside':'outside';if(tasks.has(id))return tasks.get(id);const names=interior?inside:exterior,jobs=names.flatMap(n=>channels.map(c=>[n+'/'+c,n+'/'+c+'.webp',true]));jobs.push(...(interior?[['menu','menu.webp',false],['tabletop','tabletop.webp',false]]:[['sign','sign.webp',false],['fringe','fringe.png',true]]));let done=0;const work=Promise.all(jobs.map(async args=>{await load(...args);report(++done/jobs.length);}));tasks.set(id,work);return work.catch(e=>{tasks.delete(id);throw e;});}
export function tikiTextures(){return [...textures.values()];}
export function tikiMaterials(interior=false){
 const surface=(n,roughness=1,normal=.65)=>new T.MeshStandardMaterial({name:'Tiki '+n,map:textures.get(n+'/basecolor'),normalMap:textures.get(n+'/normal'),normalScale:new T.Vector2(normal,normal),roughnessMap:textures.get(n+'/roughness'),roughness,aoMap:textures.get(n+'/ao'),aoMapIntensity:.65,metalnessMap:textures.get(n+'/metalness'),metalness:0});
 const m={rock:surface('lava-rock',1,1.1),wood:surface('carved-wood',.94,.65),thatch:surface('thatch',1,.85),bamboo:surface('bamboo',.78,.48)};
 m.thatch.side=T.DoubleSide;m.thatch.displacementMap=textures.get('thatch/height');m.thatch.displacementScale=.035;m.thatch.displacementBias=-.012;
 m.thatch.onBeforeCompile=s=>{s.uniforms.tikiHeight={value:textures.get('thatch/height')};s.fragmentShader='uniform sampler2D tikiHeight;\n'+s.fragmentShader;let code=`vec2 tikiShift=vec2(0.);vec3 qx=dFdx(-vViewPosition),qy=dFdy(-vViewPosition);vec2 sx=dFdx(vMapUv),sy=dFdy(vMapUv);vec3 tangent=normalize(qx*sy.y-qy*sx.y),bitangent=normalize(-qx*sy.x+qy*sx.x);vec3 eye=normalize(vViewPosition);vec2 ray=vec2(dot(eye,tangent),dot(eye,bitangent))/max(.25,abs(dot(eye,normalize(cross(tangent,bitangent)))))*.035;float layer=0.;for(int i=0;i<6;i++){float h=1.-texture2D(tikiHeight,vMapUv-tikiShift).r;if(layer<h){tikiShift+=ray/6.;layer+=1./6.;}}\n`;s.fragmentShader=s.fragmentShader.replace('#include <map_fragment>',code+T.ShaderChunk.map_fragment.replaceAll('vMapUv','(vMapUv-tikiShift)'));for(const [chunk,uv]of[['normal_fragment_maps','vNormalMapUv'],['roughnessmap_fragment','vRoughnessMapUv'],['aomap_fragment','vAoMapUv']])s.fragmentShader=s.fragmentShader.replace('#include <'+chunk+'>',T.ShaderChunk[chunk].replaceAll(uv,'('+uv+'-tikiShift)'));};m.thatch.customProgramCacheKey=()=> 'tiki-thatch-pom-six-v76';
 m.fringe=new T.MeshStandardMaterial({name:'Layered generated thatch fringe',map:textures.get('fringe'),normalMap:textures.get('thatch/normal'),normalScale:new T.Vector2(.4,.4),side:T.DoubleSide,alphaTest:.42,roughness:1});
 m.sign=new T.MeshStandardMaterial({name:'Generated Lantern Reef sign',map:textures.get('sign'),emissiveMap:textures.get('sign'),emissive:0xffd18f,emissiveIntensity:.38,normalMap:textures.get('carved-wood/normal'),normalScale:new T.Vector2(.14,.14),roughness:.7});
 m.dark=m.wood.clone();m.dark.name='Tarred wood and socket hardware';m.dark.color.setHex(0x342b20);m.dark.roughness=.85;
 m.rope=m.bamboo.clone();m.rope.name='Fibre cord';m.rope.color.setHex(0x918266);m.rope.roughness=1;
 m.glass=new T.MeshStandardMaterial({name:'Worn amber glass',map:textures.get('bamboo/basecolor'),normalMap:textures.get('bamboo/normal'),normalScale:new T.Vector2(.035,.035),color:0x374a32,roughness:.23,metalness:.14});
 m.redEye=new T.MeshStandardMaterial({name:'Recessed red ember lenses',map:textures.get('carved-wood/basecolor'),emissive:0xff3010,emissiveIntensity:3.2,color:0x5a1407,roughness:.22});
 m.bulb=new T.MeshStandardMaterial({name:'Vintage colored glass bulbs',map:textures.get('bamboo/basecolor'),normalMap:textures.get('bamboo/normal'),normalScale:new T.Vector2(.02,.02),emissive:0xfff0bc,emissiveIntensity:2.7,roughness:.24,vertexColors:true});
 if(interior){m.mat=surface('woven-mat',1,.82);m.floor=surface('floor-slate',.86,.75);m.vinyl=surface('red-vinyl',.53,.38);m.counter=surface('counter-wood',.56,.36);m.menu=new T.MeshStandardMaterial({name:'Generated period menu',map:textures.get('menu'),roughness:.72,side:T.DoubleSide});m.tabletop=new T.MeshStandardMaterial({name:'Generated bottles ceramics and coaster atlas',map:textures.get('tabletop'),normalMap:textures.get('counter-wood/normal'),normalScale:new T.Vector2(.08,.08),roughness:.38});m.brass=m.bamboo.clone();m.brass.color.setHex(0xd8ac57);m.brass.metalness=.7;m.brass.roughness=.44;m.paper=m.mat.clone();m.paper.color.setHex(0xd8c9aa);}
 return m;
}
